/** 
 * Returns the display name for a time zone. The display name is the name specified by the Java TimeZone class for non-"en" locales or a friendly english name for "en", with the addition of the GMT offset for human readability.
 * @param zoneID the time zone to get the name for.
 * @param locale the locale to use.
 * @return the display name for the time zone.
 */
public static String getTimeZoneName(String zoneID, Locale locale) {
  if (zoneID == null) {
    throw new IllegalArgumentException("zoneID cannot be null");
  }
  TimeZone zone = TimeZone.getTimeZone(zoneID);
  StringBuffer buf = new StringBuffer();
  int offset = zone.getRawOffset();
  if (zone.inDaylightTime(new Date()) && zone.useDaylightTime()) {
    offset += (int) JiveConstants.HOUR;
  }
  buf.append("(");
  if (offset < 0) {
    buf.append("GMT-");
  } else {
    buf.append("GMT+");
  }
  offset = Math.abs(offset);
  int hours = offset / (int) JiveConstants.HOUR;
  int minutes = (offset % (int) JiveConstants.HOUR) / (int) JiveConstants.MINUTE;
  buf.append(hours).append(":");
  if (minutes < 10) {
    buf.append("0").append(minutes);
  } else {
    buf.append(minutes);
  }
  buf.append(") ");
  if ("en".equals(locale.getLanguage())) {
    String name = null;
    try {
      name = nameMap.get(zoneID);
    } catch (NullPointerException | ClassCastException e) {
      name = zoneID;
    }
    if (name == null) {
      name = zoneID;
    }
    buf.append(name);
  } else {
    buf.append(zone.getDisplayName(true, TimeZone.LONG, locale).replace('_', ' ').replace('/', ' '));
  }
  return buf.toString();
}
